#include <iostream>
#include <string>
#include "../include/url_parser.h"

int main(int argc, char* argv[]) {
    if (argc < 2) return 1;

    std::string url = argv[1];

    std::cout << url_parser::URL::is_valid_url(url) << std::endl;

    url_parser::URL parser(url);

    std::cout << url_parser::is_scheme_valid(parser.scheme()) << std::endl;
    std::cout << url_parser::is_host_valid(parser.host()) << std::endl;
    std::cout << url_parser::is_port_valid(parser.port()) << std::endl;

    auto path_segments = url_parser::split_path(parser.path());
    std::cout << path_segments.size() << std::endl;

    for (const auto& segment : path_segments) {
        std::cout << segment << std::endl;
    }

    return 0;
}


